                   @if (tenantOpen()) {
                     <div class="absolute right-0 mt-2 w-60 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-2xl shadow-xl z-50 p-2">
                       @for (tenant of auth.tenants(); track tenant.id) {
