       })
       .catch(err => {
         this.error.set(err.message || 'Erro ao conectar com o servidor');
         this.loading.set(false);
       });
   }

   backToStep1() {
     this.step.set(1);
     this.error.set('');
     this.status.set('Informe seu email ou telefone para receber um código');
   }

   goLogin() {
     this.router.navigate(['/login']);
   }
 }

