       }

       @if (viewMode() === 'graph') {
         <!-- Graph mode -->
         <div class="bg-white dark:bg-slate-900 rounded-3xl shadow-sm ring-1 ring-slate-200 dark:ring-slate-800 p-8">
           @if (loading()) {
