     </div>

     <!-- Modal de Compartilhamento -->
     <app-modal [isOpen]="showShareModal()" title="Compartilhar Evolução" [showFooter]="false" maxWidth="560px"
       (closed)="closeShareModal()">
       @if (evoToShare()) {
         <div class="space-y-5">
