     const colors = ['#3B82F6', '#8B5CF6', '#EC4899', '#F59E0B', '#10B981', '#EF4444', '#06B6D4', '#84CC16'];
     const index = name ? name.charCodeAt(0) % colors.length : 0;
     return colors[index];
   }

   calculateTotal(plano: any): number {
