   vertical-align: middle;
 }
 .dark .table th { border-bottom-color: var(--gray-700); }
 .dark .table td { border-bottom-color: var(--gray-700); color: var(--gray-300); }
 .table tbody tr { transition: background 0.15s; }
 .table tbody tr:hover { background: var(--gray-50); }
 .dark .table tbody tr:hover { background: rgba(var(--primary-rgb), 0.05); }

