 .page { max-width: 1200px; }
 .page h1 { margin: 0; font-size: 24px; font-weight: 800; color: var(--text); letter-spacing: -0.02em; }
 .subtitle { color: var(--text-secondary); font-size: 14px; margin: 4px 0 0; font-weight: 500; }

 /* Header */
 .header {
   display: flex;
   justify-content: space-between;
   align-items: flex-start;
   margin-bottom: 24px;
   gap: 16px;
 }

 /* Forms */
 .form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
 .form-group { display: flex; flex-direction: column; gap: 6px; }
 .form-group label {
   font-size: 11px;
   font-weight: 700;
   color: var(--gray-400);
   text-transform: uppercase;
   letter-spacing: 0.1em;
 }
 .full { grid-column: 1 / -1; }
 .form-actions {
   display: flex;
   justify-content: flex-end;
   gap: 8px;
   margin-top: 24px;
   padding-top: 16px;
