 /* Empty State */
 .empty {
   text-align: center;
   padding: 60px 20px;
   color: var(--gray-400);
 }
 .empty p { margin-top: 12px; font-size: 14px; }

 /* Actions */
 .actions { display: flex; gap: 4px; }

 /* Text */
 .text-muted { color: var(--gray-500); font-size: 13px; }

 /* Animations */
 .animate-in { animation: fadeIn 0.3s ease-in-out; }
 @keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

 /* Scrollbar */
 .custom-scrollbar::-webkit-scrollbar { width: 4px; }
 .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
 .custom-scrollbar::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 2px; }

 /* Responsive */
 @media (max-width: 768px) {
   .form-grid { grid-template-columns: 1fr; }
   .info-grid { grid-template-columns: 1fr; }
   .header { flex-direction: column; }
 }

 /* Icon Tooltip */
 .icon-tooltip {
   position: fixed;
   z-index: 9999;
   background: #19212E;
   color: #FFFFFF;
   padding: 6px 12px;
   border-radius: 8px;
   font-size: 12px;
