cat > /tmp/test-theme.mjs <<'EOF'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

await page.goto('http://localhost:4200/', { waitUntil: 'networkidle' });

// 1) Landing tema claro, accent padrão
await page.evaluate(() => {
  localStorage.setItem('theme', 'light');
  localStorage.setItem('accentColor', '#b45309'); // amber-700
});
await page.reload({ waitUntil: 'networkidle' });

// aplicar accent no runtime
await page.evaluate(() => {
  const s = document.documentElement.style;
  s.setProperty('--primary', '#b45309');
  s.setProperty('--primary-rgb', '180, 83, 9');
  s.setProperty('--on-primary-rgb', '255, 255, 255');
});

// checar botões primários da landing
const btns = await page.evaluate(() => {
  const els = [...document.querySelectorAll('a, button')];
  return els.filter(e => {
    const bg = getComputedStyle(e).backgroundColor;
    return bg === 'rgb(180, 83, 9)' || bg.includes('83, 9');
  }).map(e => {
    const cs = getComputedStyle(e);
    return { text: e.textContent?.trim().slice(0, 25), bg: cs.backgroundColor, color: cs.color };
  });
});
console.log('Botões bg-primary (amber):', JSON.stringify(btns, null, 1));

// contraste texto/bg
function lum(hex) {
  const c = hex.match(/\d+/g).map(Number).map(v => { const s = v/255; return s <= 0.03928 ? s/12.92 : Math.pow((s+0.055)/1.055, 2.4); });
  return 0.2126*c[0] + 0.7152*c[1] + 0.0722*c[2];
}
for (const b of btns) {
  const bg = b.bg.match(/\d+/g).map(Number), fg = b.color.match(/\d+/g).map(Number);
  const l1 = lum(bg.join(',')), l2 = lum(fg.join(','));
  const ratio = (Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05);
  console.log(`  "${b.text}" ratio=${ratio.toFixed(2)}:1 ${ratio >= 4.5 ? 'OK' : 'FALHA'}`);
}

await browser.close();
EOF
