from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    b = p.chromium.launch()
    page = b.new_page(viewport={"width": 1280, "height": 900})
    page.goto("http://localhost:4200/", wait_until="networkidle")

    # Tema claro + accent amber-700
    page.evaluate("""() => {
      localStorage.setItem('theme', 'light');
      localStorage.setItem('accentColor', '#b45309');
      const s = document.documentElement.style;
      s.setProperty('--primary', '#b45309');
      s.setProperty('--primary-rgb', '180, 83, 9');
      s.setProperty('--primary-dark', '#8f4207');
      s.setProperty('--on-primary-rgb', '255, 255, 255');
    }""")
    page.reload(wait_until="networkidle")

    def lum(rgb):
        c = [int(v) for v in rgb]
        c = [(v/255) for v in c]
        c = [(v/12.92 if v <= 0.03928 else ((v+0.055)/1.055)**2.4) for v in c]
        return 0.2126*c[0] + 0.7152*c[1] + 0.0722*c[2]

    # Botões com bg = rgb(180,83,9) (amber) na landing
    data = page.evaluate("""() => {
      return [...document.querySelectorAll('a, button')]
        .filter(e => getComputedStyle(e).backgroundColor === 'rgb(180, 83, 9)')
        .map(e => {
          const cs = getComputedStyle(e);
          return { text: e.textContent.trim().slice(0, 30), bg: cs.backgroundColor, color: cs.color };
        });
    }""")
    print("Botões amber encontrados:", len(data))
    for d in data:
        bg_rgb = [int(x) for x in d["bg"].split("(")[1].rstrip(")").split(",")]
        fg_rgb = [int(x) for x in d["color"].split("(")[1].rstrip(")").split(",")]
        l1, l2 = lum(bg_rgb), lum(fg_rgb)
        ratio = (max(l1,l2)+0.05)/(min(l1,l2)+0.05)
        print(f'  "{d["text"]}" ratio={ratio:.2f}:1 {"OK" if ratio>=4.5 else "FALHA"} (fg={d["color"]})')

    # Testar accent CLARO antigo (amber-500 #f59e0b) — on-primary deve ficar escuro
    page.evaluate("""() => {
      const s = document.documentElement.style;
      s.setProperty('--primary', '#f59e0b');
      s.setProperty('--primary-rgb', '245, 158, 11');
      s.setProperty('--on-primary-rgb', '15, 23, 42');
    }""")
