            out.bgRule = r.cssText.slice(0, 200);
          }
          if (r.selectorText && r.selectorText.includes('.text-on-primary')) {
            out.onRule = r.cssText.slice(0, 200);
          }
        }
      }
      // lista de classes aplicadas com style
      out.matched = [...a.classList].filter(c => {
        try { return a.matches('.' + c.replace(/[:/\\]/g, '\\\\$&')); } catch { return true; }
      });
      const cs = getComputedStyle(a);
      out.bg = cs.backgroundColor; out.color = cs.color;
      return out;
    }""")
    print(info)
    b.close()
EOF
