from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    b = p.chromium.launch(executable_path='/Users/amauri/Library/Caches/ms-playwright/chromium-1208/chrome-mac-x64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing')
    page = b.new_page(viewport={"width": 1280, "height": 900})
    page.goto("http://localhost:4200/", wait_until="networkidle")
    page.wait_for_timeout(1500)

    # auditar TODOS os elementos visíveis: texto vs fundo efetivo
    issues = page.evaluate("""() => {
      function lum(rgb) {
        const m = rgb.match(/rgba?\\((\\d+),\\s*(\\d+),\\s*(\\d+)/);
        if (!m) return null;
        let c = [m[1], m[2], m[3]].map(v => v/255).map(v => v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4));
        return 0.2126*c[0] + 0.7152*c[1] + 0.0722*c[2];
      }
      const issues = [];
      const seen = new Set();
      for (const el of document.querySelectorAll('body *')) {
        const cs = getComputedStyle(el);
        if (!el.textContent || !el.textContent.trim()) continue;
        if (cs.display === 'none' || cs.visibility === 'hidden') continue;
        const color = cs.color;
        if (color === 'rgba(0, 0, 0, 0)') continue;
        // encontrar o fundo efetivo (sobe a árvore até achar opaco)
        let bg = 'rgb(255, 255, 255)', node = el;
        for (let i = 0; i < 6 && node; i++) {
          const b = getComputedStyle(node).backgroundColor;
          if (b !== 'rgba(0, 0, 0, 0)') { bg = b; break; }
          node = node.parentElement;
        }
        const l1 = lum(color), l2 = lum(bg);
        if (l1 === null || l2 === null) continue;
        const ratio = (Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05);
        const isSmall = parseFloat(cs.fontSize) < 18.66 || parseFloat(cs.fontWeight) < 700;
        const need = isSmall ? 4.5 : 3;
        // ignorar elementos de ícone ou decorativos
        const text = el.textContent.trim().slice(0, 35);
        if (ratio < need && text.length > 0 && !text.startsWith('{') && !text.startsWith('{{')) {
          const key = text + '|' + ratio.toFixed(1);
          if (!seen.has(key)) {
            seen.add(key);
            issues.push({ tag: el.tagName, text, ratio: ratio.toFixed(2), fg: color, bg, need, cls: el.className?.toString().slice(0, 60) || '' });
          }
        }
      }
      return issues.slice(0, 30);
    }""")
    print(f"Problemas de contraste encontrados: {len(issues)}")
    for i in issues:
        print(f'  [{i["tag"]}] "{i["text"]}" ratio={i["ratio"]} (precisa {i["need"]}) fg={i["fg"]} bg={i["bg"]} cls={i["cls"]}')
    b.close()
EOF
