from playwright.sync_api import sync_playwright

def audit(page, url, label):
    page.goto(url, wait_until="networkidle")
    page.wait_for_timeout(1500)
    issues = page.evaluate("""() => {
      function parse(c) {
        const m = c.match(/rgba?\\((\\d+),\\s*(\\d+),\\s*(\\d+)(?:,\\s*([\\d.]+))?\\)/);
        if (!m) return null;
        return [ +m[1], +m[2], +m[3], m[4] === undefined ? 1 : +m[4] ];
      }
      function comp(fg, bg) { // compor fg com alfa sobre bg opaco
        const a = fg[3];
        return fg.slice(0,3).map((v,i) => Math.round(v*a + bg[i]*(1-a)));
      }
      function lum(rgb) {
        let c = rgb.map(v => v/255).map(v => v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4));
        return 0.2126*c[0] + 0.7152*c[1] + 0.0722*c[2];
      }
      const issues = [];
      for (const el of document.querySelectorAll('body *')) {
        const cs = getComputedStyle(el);
        if (!el.textContent || !el.textContent.trim()) continue;
        if (cs.display === 'none' || cs.visibility === 'hidden') continue;
        const color = parse(cs.color);
        if (!color || color[3] === 0) continue;
        let bg = [255,255,255,1], node = el;
        for (let i = 0; i < 8 && node; i++) {
          const b = parse(getComputedStyle(node).backgroundColor);
          if (b && b[3] > 0) { bg = comp(b, bg); break; }
          node = node.parentElement;
        }
        const fgc = comp(color, bg);
        const l1 = lum(fgc), l2 = lum(bg);
        const ratio = (Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05);
        const size = parseFloat(cs.fontSize);
        const isSmall = size < 18.66 || parseFloat(cs.fontWeight) < 700;
        const need = isSmall ? 4.5 : 3;
        const text = el.textContent.trim().slice(0, 35);
        if (ratio < need && text.length > 0) {
          issues.push({ tag: el.tagName, text, ratio: ratio.toFixed(2), need, cls: (el.className||'').toString().slice(0, 55), size });
        }
      }
      return issues.slice(0, 15);
    }""")
    print(f"\n=== {label}: {len(issues)} problemas REAIS")
    for i in issues:
        print(f'  [{i["tag"]}] "{i["text"]}" ratio={i["ratio"]} (need {i["need"]}, size {i["size"]}px) cls={i["cls"]}')

with sync_playwright() as p:
    b = p.chromium.launch(executable_path='/Users/amauri/Library/Caches/ms-playwright/chromium-1208/chrome-mac-x64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing')
    page = b.new_page(viewport={"width": 1280, "height": 900})
    page.goto("http://localhost:4200/login", wait_until="networkidle")
    page.wait_for_timeout(1000)
    page.fill('input[type="email"], input[placeholder*="mail"], input[name="email"]', 'sarah@edupsych.com')
    page.fill('input[type="password"]', '123456')
    page.click('button[type="submit"]')
    page.wait_for_timeout(3500)
    audit(page, "http://localhost:4200/", "Landing")
    audit(page, "http://localhost:4200/login", "Login")
    audit(page, "http://localhost:4200/app/dashboard", "Dashboard")
    audit(page, "http://localhost:4200/app/configuracoes", "Configurações")
    b.close()
EOF
