+++ backend/src/index.ts	
@@ -1,61 +1,79 @@
 import express from 'express';
 import cors from 'cors';
 import session from 'express-session';
 import passport from 'passport';
 import path from 'path';
 import dotenv from 'dotenv';
+import helmet from 'helmet';
+import rateLimit from 'express-rate-limit';
 import routes from './routes';
 import { errorHandler } from './middleware';
 import configurePassport from './config/passport';

 dotenv.config();

 const app = express();
 const PORT = process.env.PORT || 3000;

 // Session configuration
+if (!process.env.SESSION_SECRET) {
+  throw new Error('SESSION_SECRET não definido. Configure o backend/.env antes de subir o servidor.');
+}
 app.use(session({
-  secret: process.env.SESSION_SECRET || 'psicopedagoga-session-secret-2026',
+  secret: process.env.SESSION_SECRET,
   resave: false,
   saveUninitialized: false,
   cookie: {
     secure: process.env.NODE_ENV === 'production',
     maxAge: 24 * 60 * 60 * 1000 // 24 hours
   }
 }));

 // Initialize Passport
 app.use(passport.initialize());
 app.use(passport.session());

 // Configure Passport strategies
 configurePassport();

 // CORS configuration
 app.use(cors({
   origin: (process.env.FRONTEND_URL || 'http://localhost:4200').split(',').map((u: string) => u.trim()),
   credentials: true
 }));

+app.use(helmet({
+  crossOriginResourcePolicy: { policy: 'cross-origin' },
+}));
+
+// Rate limiting global (API)
+app.use('/api', rateLimit({
+  windowMs: 60 * 1000,
+  limit: 300,
+  standardHeaders: true,
+  legacyHeaders: false,
+  message: { error: 'Muitas requisições. Tente novamente em instantes.' },
+}));
+
 app.use(express.json());

 // Serve uploaded files
 app.use('/api/uploads', express.static(path.join(__dirname, '../uploads')));

 // Routes
 app.use('/api', routes);

 // Error handler
 app.use(errorHandler);

 // Evitar derrubar o processo inteiro por erros em handlers async
 process.on('unhandledRejection', (reason) => {
   console.error('[unhandledRejection]', reason);
 });
 process.on('uncaughtException', (err) => {
   console.error('[uncaughtException]', err);
 });

 app.listen(PORT, () => {
   console.log(`Backend rodando na porta ${PORT}`);
 });

Index: backend/src/middleware/auth.ts
===================================================================
--- backend/src/middleware/auth.ts	
+++ backend/src/middleware/auth.ts	
@@ -1,107 +1,109 @@
 import { Request, Response, NextFunction } from 'express';
 import jwt from 'jsonwebtoken';
 import prisma from '../lib/prisma';
 import { enforceTenantStatus } from '../lib/billing';

-const JWT_SECRET = process.env.JWT_SECRET || 'psicopedagoga-secret-key-2026';
+const JWT_SECRET: string = process.env.JWT_SECRET || (() => {
+  throw new Error('JWT_SECRET não definido. Configure o backend/.env antes de subir o servidor.');
+})();

 export const authenticate = async (req: Request, res: Response, next: NextFunction) => {
   const authHeader = req.headers.authorization;
   if (!authHeader?.startsWith('Bearer ')) {
     return res.status(401).json({ error: 'Token não fornecido' });
   }

   let payload: any;
   try {
     payload = jwt.verify(authHeader.split(' ')[1], JWT_SECRET);
   } catch {
     return res.status(401).json({ error: 'Token inválido' });
   }

   try {
     const user = await prisma.user.findUnique({ where: { id: payload.sub } });
     if (!user) {
       return res.status(401).json({ error: 'Token inválido' });
     }

     if (!user.active) {
       return res.status(403).json({ error: 'Conta não ativada. Verifique seu email ou reenvie o link de ativação.' });
     }

     const memberships = await prisma.membership.findMany({
       where: { userId: user.id, active: true },
       orderBy: { createdAt: 'asc' },
       include: { tenant: { include: { subscription: true } } },
     });

     if (memberships.length === 0) {
       return res.status(403).json({ error: 'Sem vínculo com nenhuma clínica. Fale com o administrador.' });
     }

     const headerTenantId = String(req.headers['x-tenant-id'] || '');
     let membership = headerTenantId
       ? memberships.find((m) => m.tenantId === headerTenantId)
       : memberships.find((m) => m.tenant.status !== 'BLOQUEADO');

     if (!membership) {
       return res.status(403).json({ error: 'Assinatura da clínica vencida ou bloqueada. Entre em contato com o suporte.' });
     }

     await enforceTenantStatus(membership.tenant);

     if (membership.tenant.status === 'BLOQUEADO') {
       return res.status(403).json({ error: 'Assinatura da clínica vencida ou bloqueada. Entre em contato com o suporte.' });
     }

     req.user = {
       id: user.id,
       name: user.name,
       email: user.email,
       role: membership.role,
       tenantId: membership.tenantId,
       tenantRole: membership.role,
       tenant: {
