   if (!responsible) {
     return res.json({ patients: [], pendingAnamnese: 0, upcomingAppointments: 0 });
   }

   const patients = await db.paciente.findMany({
     where: { responsibleId: responsible.id, active: true },
     include: { school: true }
   });

